#!/bin/sh
# picodrive for the Miyoo Mini Flip from libretro/picodrive @ 50b8b478 plus the
# submodule commits that tree pins. platform=...-armasm keeps the ARM asm
# (Cyclone 68k, DrZ80, asm renderers/memory/ym2612) and the SH2/SVP DRCs on.
. "$(dirname "$0")/common.sh"
fetch picodrive libretro/picodrive 1890c2932234c9d30f4cd3851d02228baae8f09e 123871ce468bc31f824df9273415215527ded2bdaadffd0503a97149aa06d523
fetch picodrive-cyclone irixxxx/cyclone68000 3ac7cf1bdeecb60e2414980e8dc72ff092f69769 e570e121721441c1bf8015a8bce8614b73954e2344b983b3650e591952f74a6c picodrive/cpu/cyclone
fetch picodrive-libchdr irixxxx/libchdr e62ac5995b1c7ef65ece35293914843b8ee57d49 59b99005d3d6317a0d1e45e1c4abf0e551070dbf32c8fdc66ed5b4ae6d8ea702 picodrive/pico/cd/libchdr
fetch picodrive-emu2413 digital-sound-antiques/emu2413 a2dfc20ff507e4fd075cd325620bcea655e2c1f7 bd816079cfbf13c56a260c095d6b8e260c2f877e5b13f50d4e570b96e8b92830 picodrive/pico/sound/emu2413
fetch picodrive-dr_libs mackron/dr_libs dd762b861ecadf5ddd5fb03e9ca1db6707b54fbb 8f0be8a4aa27cd4ddaba41acbb845b1641964f2cc2f5a5f7b4b72f73368c1c12 picodrive/platform/common/dr_libs
fetch picodrive-libpicofe irixxxx/libpicofe 9ed5822606dd7ff20a782a882e8fd611cb53ba88 458519aaa70916528e593f1f052aa45f704670fba094b409478a8197e6f076a7 picodrive/platform/libpicofe
# Cyclone.s is generated by a host-run tool (cyclone_gen); the toolchain image
# has no native compiler, so build/run it with the host g++ (output is plain
# ARM asm text, independent of the host).
make -s -C "$W/src/picodrive/cpu/cyclone" CONFIG_FILE=../cyclone_config.h CC=gcc CXX=g++ > "$W/logs/picodrive-cyclone.log" 2>&1 \
  || { tail "$W/logs/picodrive-cyclone.log"; echo "RESULT picodrive FAILED (cyclone_gen)"; exit 1; }
# No `make clean` (the fresh tree needs none): at 1890c29 clean also deletes the host-made Cyclone.s.
dk src/picodrive "make -j4 -f Makefile.libretro $XCW AS=arm-linux-gnueabihf-as platform=unix-armv7-hardfloat-neon-armasm" > "$W/logs/picodrive.log" 2>&1 ||
  { tail -20 "$W/logs/picodrive.log"; echo "RESULT picodrive FAILED"; exit 1; }
check_so src/picodrive/picodrive_libretro.so picodrive_libretro.so
